/* DateForge 纯函数内核（无 DOM 依赖，可被 Node 单测直接加载） */
var DF = (function(){
  'use strict';
  function pad2(n){ return (n<10?'0':'')+n; }
  function isLeap(y){ return (y%4===0 && y%100!==0) || y%400===0; }
  var DIM = [31,28,31,30,31,30,31,31,30,31,30,31];
  function dim(y,m){ return m===2 && isLeap(y) ? 29 : DIM[m-1]; }
  function valid(y,m,d){
    return Number.isInteger(y) && Number.isInteger(m) && Number.isInteger(d) &&
      y>=1 && y<=9999 && m>=1 && m<=12 && d>=1 && d<=dim(y,m);
  }
  /* Howard Hinnant days-from-civil：返回自 1970-01-01 起的天数（可为负） */
  function toSerial(y,m,d){
    var yy = y - (m<=2 ? 1 : 0);
    var era = Math.floor(yy/400);
    var yoe = yy - era*400;
    var doy = Math.floor((153*(m + (m>2 ? -3 : 9)) + 2)/5) + d - 1;
    var doe = yoe*365 + Math.floor(yoe/4) - Math.floor(yoe/100) + doy;
    return era*146097 + doe - 719468;
  }
  function fromSerial(n){
    var z = n + 719468;
    var era = Math.floor(z/146097);
    var doe = z - era*146097;
    var yoe = Math.floor((doe - Math.floor(doe/1460) + Math.floor(doe/36524) - Math.floor(doe/146096))/365);
    var y = yoe + era*400;
    var doy = doe - (365*yoe + Math.floor(yoe/4) - Math.floor(yoe/100));
    var mp = Math.floor((5*doy + 2)/153);
    var d = doy - Math.floor((153*mp+2)/5) + 1;
    var m = mp + (mp<10 ? 3 : -9);
    return { y: y + (m<=2 ? 1 : 0), m: m, d: d };
  }
  function parse(str){
    if(typeof str !== 'string') return null;
    var s = str.trim();
    var m = s.match(/^(\d{4})[-/.年]?(\d{1,2})[-/.月]?(\d{1,2})日?$/);
    if(!m) return null;
    var o = { y:+m[1], m:+m[2], d:+m[3] };
    return valid(o.y,o.m,o.d) ? o : null;
  }
  function fmt(o, sep){
    sep = sep === undefined ? '-' : sep;
    return o.y + sep + pad2(o.m) + sep + pad2(o.d);
  }
  /* 星期：0=周一 … 6=周日（1970-01-01 是周四） */
  function weekday(o){
    var s = toSerial(o.y,o.m,o.d);
    return ((s+3)%7+7)%7;
  }
  var WD_ZH = ['周一','周二','周三','周四','周五','周六','周日'];
  function weekdayName(i){ return WD_ZH[i]; }
  function diffDays(a,b){ return toSerial(b.y,b.m,b.d) - toSerial(a.y,a.m,a.d); }
  /* Y/M/D 分解差（含符号，锚点法：a + Ny+Nm 收敛后再数天） */
  function diffYMD(a,b){
    var sign = 1;
    if(diffDays(a,b) < 0){ var t=a; a=b; b=t; sign=-1; }
    var tm = (b.y - a.y)*12 + (b.m - a.m);
    var anchor = addMonths(a, tm);
    if(diffDays(anchor, b) < 0){ tm -= 1; anchor = addMonths(a, tm); }
    var years = Math.floor(tm/12);
    return { sign:sign, years:years, months: tm - years*12,
             days: diffDays(anchor, b), totalDays: Math.abs(diffDays(a,b)) };
  }
  function addDays(o,n){ return fromSerial(toSerial(o.y,o.m,o.d) + n); }
  function addMonths(o,n){
    var idx = (o.y*12 + (o.m-1)) + n;
    var y = Math.floor(idx/12), m = idx - y*12 + 1;
    var d = Math.min(o.d, dim(y,m));
    return { y:y, m:m, d:d };
  }
  function addYears(o,n){
    var y = o.y + n;
    return { y:y, m:o.m, d: Math.min(o.d, dim(y,o.m)) };
  }
  /* ISO 8601 周数 */
  function isoWeek(o){
    var s = toSerial(o.y,o.m,o.d);
    var dow = ((s+3)%7+7)%7;          /* 0=周一 */
    var thursday = s - dow + 3;
    var t = fromSerial(thursday);
    var week = Math.floor((thursday - toSerial(t.y,1,1))/7) + 1;
    return { year: t.y, week: week };
  }
  function dayOfYear(o){ return toSerial(o.y,o.m,o.d) - toSerial(o.y,1,1) + 1; }
  /* 工作日（周一~周五）计数，含首尾两端 */
  function workdays(a,b){
    var neg = false;
    if(diffDays(a,b) < 0){ var t=a; a=b; b=t; neg=true; }
    var total = diffDays(a,b) + 1;
    var weeks = Math.floor(total/7), rem = total%7;
    var cnt = weeks*5;
    var wd = weekday(a);
    for(var i=0;i<rem;i++){ if(((wd+i)%7) < 5) cnt++; }
    return neg ? -cnt : cnt;
  }
  /* 年龄：生日→参考日 Y/M/D + 下次生日倒计时 */
  function age(birth, ref){
    var a = diffYMD(birth, ref);
    var ny = ref.y;
    var bm = birth.m, bd = birth.d;
    function mk(y){ return { y:y, m:bm, d: Math.min(bd, dim(y,bm)) }; }
    var next = mk(ny);
    if(diffDays(ref, next) <= 0) next = mk(ny+1);
    return { years:a.years, months:a.months, days:a.days, totalDays:a.totalDays,
             nextBirthday: next, nextBirthdayDays: diffDays(ref, next) };
  }
  function toUnix(o){ return toSerial(o.y,o.m,o.d)*86400; }
  function fromUnix(sec){
    var days = Math.floor(sec/86400);
    return fromSerial(days);
  }
  function today(){
    var d = new Date();
    return { y:d.getFullYear(), m:d.getMonth()+1, d:d.getDate() };
  }
  return {
    pad2:pad2, isLeap:isLeap, dim:dim, valid:valid,
    toSerial:toSerial, fromSerial:fromSerial, parse:parse, fmt:fmt,
    weekday:weekday, weekdayName:weekdayName,
    diffDays:diffDays, diffYMD:diffYMD,
    addDays:addDays, addMonths:addMonths, addYears:addYears,
    isoWeek:isoWeek, dayOfYear:dayOfYear, workdays:workdays,
    age:age, toUnix:toUnix, fromUnix:fromUnix, today:today
  };
})();
if(typeof module!=='undefined' && module.exports){ module.exports = DF; }
if(typeof window!=='undefined'){ window.__DATEFORGE__ = DF; }
